135	    /**
136	     * Internal seed helper: truncates all test-database tables, invalidates
137	     * ORM collection caches, then seeds system users, locales, and countries.
138	     *
139	     * **For the `composer seed-tests` workflow use the CLI scripts instead:**
140	     * `tools/seed-truncate.php` and `tools/seed-insert.php` achieve the same
141	     * result via process isolation, which renders the `resetCollection()` calls
142	     * here unnecessary in that context. Those scripts call the low-level
143	     * `TestSuiteBootstrap` methods directly and do NOT invoke this method.
144	     *
145	     * This method exists for programmatic callers (e.g. application-level
146	     * `ComposerScripts::seedTests()`) that invoke it in a single process.
147	     * In that scenario the `resetCollection()` calls are still needed: they
148	     * clear ORM caches that may have been populated during bootstrap so that
149	     * the seed methods' `idExists()` checks query the live (post-truncation)
150	     * database rather than stale in-memory state.
151	     *
152	     * Direct callers must pre-define the <code>APP_SEED_MODE</code> constant
153	     * and call {@see self::init()} before invoking this method.
154	     * Use {@see self::seedTests()} as the proper public entry point — it
155	     * handles both prerequisites automatically.
156	     *
157	     * @throws \Application_Exception
158	     * @throws \Throwable
159	     */
160	    public static function doSeedTests() : void
161	    {
162	        echo '- Seeding test database...'.PHP_EOL;
163	
164	        TestSuiteBootstrap::truncateAllTables();
165	
166	        // Invalidate ORM collection caches that may have been populated during
167	        // bootstrap authentication. Without this, idExists() checks in the
168	        // seed methods would return stale true-values for records that were
169	        // just deleted by the truncation.
170	        AppFactory::createUsers()->resetCollection();
171	        AppFactory::createCountries()->resetCollection();
172	
173	        TestSuiteBootstrap::seedSystemUsers();
174	        TestSuiteBootstrap::seedLocales();
175	        TestSuiteBootstrap::seedCountries();
176	
177	        echo '  DONE.'.PHP_EOL;
178	    }
